/**
 * Samsung Weather hero scene library — data layer.
 *
 * Scene table schema (generated by tools/extract-samsung-hero.py from the
 * APK's assets/agsl_shader_android.json):
 *
 *   {
 *     "scenes": {
 *       "<weatherCode>_<sunStatus>_<deviceTier>": {
 *         "resources": {
 *           "FARLAND":            { "resource|average|over27|below0": "<name>" },
 *           "HUMAN"|"HURRICANE":  { ..., "loopStartTime": <frames> },
 *           "NEARLAND":           { ... },
 *           "NEARLAND_GRADATION": { ... }
 *         },
 *         "layers": {
 *           "BACKGROUND_CANVAS":  { "class": "class_N", "codeId": "code_M", "uniforms": { ... } },
 *           "SUN_AND_STAR_CANVAS"|"CLOUD_CANVAS"|"RAIN_CANVAS"|"SNOW_CANVAS"|
 *           "THUNDER_CANVAS"|"FOG_CANVAS": { ... }
 *         }
 *       }
 *     },
 *     "layerFiles":    { "<resourceName>": "<ext: webp|png>" },
 *     "characterNames": ["<name>", ...]
 *   }
 *
 * NOTE: the generated scenes.json and all binary assets are Samsung
 * copyrighted material. They are git-ignored in this repo and must be
 * generated locally from an APK you obtained yourself. See README.md.
 */

export const SUN_STATUSES = ['DAY', 'NIGHT', 'SUNRISE', 'SUNSET', 'WHITE_NIGHT', 'POLAR_NIGHT'];
export const DEVICE_TIERS = ['LOWEST', 'LOW', 'HIGH'];
export const LAYER_SLOTS = [
  'BACKGROUND_CANVAS', 'SUN_AND_STAR_CANVAS', 'CLOUD_CANVAS',
  'RAIN_CANVAS', 'SNOW_CANVAS', 'THUNDER_CANVAS', 'FOG_CANVAS',
];

/** Fetch and parse a generated scenes.json. `baseUrl` = folder containing data/. */
export async function loadSceneLibrary(baseUrl = '', fetchFn = fetch) {
  const res = await fetchFn(new URL('data/scenes.json', baseUrl.endsWith('/') ? baseUrl : baseUrl + '/'));
  if (!res.ok) throw new Error(`scenes.json not found (${res.status}). Run tools/extract-samsung-hero.py first — see apps/samsung-hero/README.md`);
  return res.json();
}

export function sceneKey(weatherCode, sunStatus, deviceTier) {
  return `${weatherCode}_${sunStatus}_${deviceTier}`;
}

/**
 * Resolve a scene like the APK does (od.b): exact key first, then the same
 * code under other sun statuses, then other device tiers.
 * Returns [key, scene] or ['', null].
 */
export function resolveScene(db, weatherCode, sunStatus = 'DAY', deviceTier = 'HIGH') {
  const tries = [sceneKey(weatherCode, sunStatus, deviceTier)];
  for (const s of ['DAY', 'NIGHT', 'SUNRISE', 'SUNSET']) tries.push(sceneKey(weatherCode, s, deviceTier));
  for (const t of DEVICE_TIERS) for (const s of [sunStatus, 'DAY', 'NIGHT']) tries.push(sceneKey(weatherCode, s, t));
  for (const k of tries) if (db?.scenes?.[k]) return [k, db.scenes[k]];
  return ['', null];
}

/**
 * Temperature outfit variant, mirroring the APK (od.b):
 * temp > 27°C -> over27, temp < 0°C -> below0, otherwise average.
 */
export function pickVariant(entry, tempC = 20) {
  if (!entry) return null;
  const name = tempC > 27 ? (entry.over27 || entry.average || entry.resource)
    : tempC < 0 ? (entry.below0 || entry.average || entry.resource)
    : (entry.average || entry.resource);
  return name || null;
}

export function hasLayer(scene, slot) { return !!scene?.layers?.[slot]; }

/** Condition label derived from the active effect canvases (snow beats the far-land family). */
export function conditionLabel(scene) {
  const L = scene?.layers || {};
  if (L.THUNDER_CANVAS) return 'Thunderstorm';
  if (L.SNOW_CANVAS && L.RAIN_CANVAS) return 'Rain & snow';
  if (L.SNOW_CANVAS) return 'Snow';
  if (L.RAIN_CANVAS) return 'Rain';
  if (L.FOG_CANVAS) return 'Foggy';
  const far = scene?.resources?.FARLAND?.average || scene?.resources?.FARLAND?.resource || '';
  if (far.includes('sand')) return 'Sandstorm';
  if (far.includes('wind')) return 'Windy';
  if (far.includes('cloud')) return 'Cloudy';
  if (far.includes('clear')) return 'Clear';
  if (far.includes('sunny')) return 'Sunny';
  return '—';
}

/** URLs for a resolved scene's artwork, relative to the samsung-hero folder. */
export function sceneArtwork(db, scene, tempC = 20, base = '') {
  const res = scene?.resources || {};
  const layer = (name) => name ? `${base}assets/layers/${name}.${db.layerFiles?.[name] || 'webp'}` : '';
  const charEntry = res.HUMAN || res.HURRICANE;
  const char = pickVariant(charEntry, tempC);
  return {
    farLand: layer(pickVariant(res.FARLAND, tempC)),
    nearLand: layer(pickVariant(res.NEARLAND, tempC)),
    gradation: layer(pickVariant(res.NEARLAND_GRADATION, tempC)),
    character: char ? `${base}assets/characters/${char}.mp4` : '',
    characterName: char || '',
    /** Character loop point in seconds (APK stores 30 fps frames). */
    loopStartSeconds: charEntry?.loopStartTime ? charEntry.loopStartTime / 30 : 0,
  };
}

/** Background-canvas (sky gradient) stops from a scene's real AGSL uniforms. */
export function skyGradient(scene) {
  const u = scene?.layers?.BACKGROUND_CANVAS?.uniforms || {};
  const pos = [0, u.skyColorGradientPos1 ?? 0.3, u.skyColorGradientPos2 ?? 0.45, u.skyColorGradientPos3 ?? 0.65, 1];
  return [u.skyColor1, u.skyColor2, u.skyColor3, u.skyColor4, u.skyColor5]
    .map((color, i) => (color ? { color, position: Math.min(1, Math.max(0, pos[i])) } : null))
    .filter(Boolean);
}

/** GLSL fragment shader that decodes the character MP4's packed alpha
 *  (port of Samsung's TransparentVideoView shader): RGB in the top 80% of
 *  the frame; alpha mask in the bottom 20%, split into 4 quadrant blocks
 *  ordered TL=1, TR=3, BL=0, BR=2, each block vertically flipped. */
export const CHARACTER_FRAGMENT_SHADER = `
precision highp float;
varying vec2 vUv;
uniform sampler2D uVideo;
uniform float uEdge;
vec4 texImg(vec2 p){ return texture2D(uVideo, p); }
float lum(vec3 c){ return length(c) / 1.7320508; }
float alphaAt(vec2 xy){
  float ax = xy.x; float ay = 1.0 - xy.y;
  float qx = ax < 0.5 ? 0.0 : 1.0; float qy = ay < 0.5 ? 0.0 : 1.0;
  float block = qy < 0.5 ? (qx < 0.5 ? 1.0 : 3.0) : (qx < 0.5 ? 0.0 : 2.0);
  float lx = fract(ax * 2.0); float ly = fract(ay * 2.0);
  vec2 sp = vec2((block + lx) * 0.25, 0.8 + (1.0 - ly) * 0.2);
  return lum(texImg(sp).rgb);
}
void main(){
  vec3 col = texImg(vec2(vUv.x, vUv.y * 0.8)).rgb;
  float a = clamp(alphaAt(vUv) * (1.0 + uEdge), 0.0, 1.0);
  gl_FragColor = vec4(col, a);
}`;

export default {
  SUN_STATUSES, DEVICE_TIERS, LAYER_SLOTS,
  loadSceneLibrary, sceneKey, resolveScene, pickVariant,
  hasLayer, conditionLabel, sceneArtwork, skyGradient,
  CHARACTER_FRAGMENT_SHADER,
};
